// Shared test helpers for the acceptance collection (TICK-331).
// Generated by docs/acceptance/guide/build/collection.py; edit it there.
// Load it in a request with:
//   const N = require('./lib/nava')({ test, expect, res, bru });
// Every code in api/errors.yaml, filled in by build/collection.py.
const REGISTERED = ['tenant_unresolved', 'invalid_token', 'idempotency_key_reuse', 'forbidden', 'invalid_idp_config', 'domain_claimed', 'onboarding_conflict', 'idempotency_in_flight', 'invalid_cursor', 'retry_later', 'rate_limited', 'not_found', 'validation_failed', 'method_not_allowed', 'not_implemented', 'internal_error', 'invalid_definition', 'entity_type_exists', 'number_prefix_taken', 'schema_breaking_change', 'workflow_definition_invalid', 'record_invalid', 'if_match_required', 'version_conflict', 'illegal_transition', 'unique_violation', 'config_secret_in_content', 'definition_secret_required', 'assignment_group_removed', 'history_too_long', 'masked_field', 'filter_too_expensive', 'field_not_writable', 'invalid_access_policy', 'export_in_progress', 'chain_alive', 'filterable_field_not_top_level', 'filterable_field_type_change', 'searchable_not_available', 'field_not_filterable', 'field_not_ready', 'filterable_field_removal_unavailable', 'index_quota_exceeded', 'field_index_busy', 'number_format_exists', 'number_format_prefix_required', 'number_format_invalid', 'numbering_templates_unavailable', 'invalid_time_zone', 'number_format_overlap', 'number_format_not_found', 'number_space_exhausted'];

const b64url = (s) => Buffer.from(s, 'base64url');

module.exports = ({ test, expect, res, bru } = {}) => {
  const N = {
    REGISTERED,
    // A runtime variable, else the environment's.
    v(name) {
      const x = bru.getVar(name);
      return x !== undefined && x !== null && x !== '' ? x : bru.getEnvVar(name);
    },
    url: (s) => bru.interpolate(s),
    header(name) {
      const h = res.getHeader(name.toLowerCase());
      return Array.isArray(h) ? h.join(', ') : h;
    },
    // The response bytes as text, exactly as received.
    text() {
      const buf = res.getDataBuffer ? res.getDataBuffer() : null;
      if (buf) return Buffer.isBuffer(buf) ? buf.toString('utf8') : Buffer.from(String(buf), 'base64').toString('utf8');
      const b = res.getBody();
      return typeof b === 'string' ? b : JSON.stringify(b);
    },
    json() {
      const b = res.getBody();
      return typeof b === 'string' ? JSON.parse(b) : b;
    },
    status(code) {
      test(`HTTP ${code}`, () => expect(res.getStatus()).to.eql(code));
    },
    // RFC 9457 problem body as api/errors.yaml registers it.
    problem(code, status) {
      test(`HTTP ${status}`, () => expect(res.getStatus()).to.eql(status));
      test(`problem+json, code ${code}`, () => {
        expect(N.header('Content-Type') || '').to.include('application/problem+json');
        const b = N.json();
        expect(b).to.include.all.keys('type', 'title', 'status', 'code', 'detail', 'instance');
        expect(b.code).to.eql(code);
        expect(b.status).to.eql(status);
        expect(b.type).to.eql('urn:nava:problem:' + code);
        expect(REGISTERED).to.include(b.code);
      });
      test("problem instance is this response's X-Request-Id", () => {
        const id = N.header('X-Request-Id');
        expect(id, 'X-Request-Id header').to.be.a('string').and.not.empty;
        expect(N.json().instance).to.eql('urn:nava:request:' + id);
      });
    },
    // validation_failed and invalid_idp_config: errors[] points at the field.
    fieldError(pointer) {
      test(`errors[] points at ${pointer}`, () => {
        const errs = N.json().errors || [];
        expect(errs.map(e => e.pointer)).to.include(pointer);
      });
    },
    // Decodes a JWT payload (no verification: the server does that).
    jwt(t) {
      return JSON.parse(b64url(String(t).split('.')[1]).toString('utf8'));
    },
    // A JWT with its payload replaced; the signature no longer matches.
    rewrite(t, change) {
      const [h, p, s] = String(t).split('.');
      const claims = JSON.parse(b64url(p).toString('utf8'));
      change(claims);
      return [h, Buffer.from(JSON.stringify(claims)).toString('base64url'), s].join('.');
    },
    // The response text never names the other tenant.
    noLeak(...needles) {
      test('response names nothing of the other tenant', () => {
        const text = N.text();
        needles.filter(Boolean).forEach(n => expect(text).to.not.include(n));
      });
    },
    me(tenant) {
      test('HTTP 200', () => expect(res.getStatus()).to.eql(200));
      test(`tenant_id is ${tenant}`, () => expect(N.json().tenant_id).to.eql(tenant));
      test('Me has the contract fields', () => {
        const b = N.json();
        expect(b).to.include.all.keys('user_id', 'tenant_id', 'groups', 'idp_alias', 'group_paths');
        expect(b.groups).to.be.an('array');
        expect(b.group_paths).to.be.an('array');
        b.group_paths.forEach(g => {
          expect(g.path, 'path relative to the tenant root').to.match(/^\//).and.not.include('/t/');
          expect(b.groups).to.include(g.id);
        });
      });
    },
    paths() { return N.json().group_paths.map(g => g.path); },
    form(o) {
      return Object.entries(o).map(([k, x]) => encodeURIComponent(k) + '=' + encodeURIComponent(x)).join('&');
    },
    // bru.sendRequest, with a 4xx/5xx returned instead of thrown.
    async send(opts) {
      try {
        return await bru.sendRequest(opts);
      } catch (e) {
        if (e && e.response) return e.response;
        throw e;
      }
    },
    // A password-grant token from the nava realm (or another realm).
    // timeout (ms), when given, bounds the call (a poll loop must never hang).
    async token(user, password, { client = 'nava-web', scope = 'openid', realm = N.v('realm'), timeout } = {}) {
      return N.send({
        url: N.url(`{{keycloak_url}}/realms/${realm}/protocol/openid-connect/token`),
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        data: N.form({ grant_type: 'password', client_id: client, scope, username: user, password }),
        ...(timeout ? { timeout } : {}),
      });
    },
    // A Keycloak master-realm admin token in kc_admin_token. It lives 60 s, so
    // every admin call fetches a fresh one.
    async kcAdmin() {
      const r = await N.token(N.v('kc_admin_user'), N.v('kc_admin_password'), { client: 'admin-cli', scope: 'openid', realm: 'master' });
      if (r.status !== 200) throw new Error('Keycloak admin token failed: HTTP ' + r.status);
      bru.setVar('kc_admin_token', r.data.access_token);
    },
    // A browser-less sign-in through a company login (S28): follows redirects
    // by hand with a small cookie jar, so no master-realm credential is used.
    // stop(url) says where the walk ends (the sign-in's redirect_uri).
    browser(stop) {
      const jar = [];
      const decode = (x) => x.replace(/&amp;/g, '&').replace(/&#61;/g, '=').replace(/&quot;/g, '"');
      const cookieHeader = (u) => jar.filter(c => u.pathname.startsWith(c.path)).map(c => c.name + '=' + c.value).join('; ');
      const keep = (r) => {
        for (const sc of [].concat(r.headers['set-cookie'] || [])) {
          const [kv, ...attrs] = sc.split(';').map(x => x.trim());
          const i = kv.indexOf('=');
          const path = ((attrs.find(a => /^path=/i.test(a)) || 'path=/').split('=')[1]) || '/';
          const k = jar.findIndex(c => c.name === kv.slice(0, i) && c.path === path);
          if (k >= 0) jar.splice(k, 1);
          if (kv.slice(i + 1) !== '') jar.push({ name: kv.slice(0, i), value: kv.slice(i + 1), path });
        }
      };
      return {
        // Opens url (POSTs form when given) and follows redirects up to stop(url).
        async go(url, form) {
          let method = form ? 'POST' : 'GET';
          let data = form ? N.form(form) : undefined;
          for (let hop = 0; hop < 20; hop++) {
            if (stop(url)) return { stopped: url, html: '' };
            const u = new URL(url);
            const r = await N.send({ url, method, data, maxRedirects: 0, validateStatus: () => true, timeout: 20000,
              headers: Object.assign({ Cookie: cookieHeader(u) }, data ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}) });
            keep(r);
            if (r.status >= 300 && r.status < 400 && r.headers.location) {
              url = new URL(r.headers.location, url).toString(); method = 'GET'; data = undefined; continue;
            }
            return { status: r.status, url, html: typeof r.data === 'string' ? r.data : JSON.stringify(r.data) };
          }
          throw new Error('too many redirects');
        },
        // Where a page is, for an error message: its URL and <title>.
        where(x) {
          const t = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(x.html || '');
          return ' (HTTP ' + x.status + ' at ' + x.url + ', title "' + (t ? t[1].trim().slice(0, 80) : 'none') + '")';
        },
        // The action of the first <form> whose tag matches re.
        formAction(html, re) {
          const m = (html.match(/<form\b[^>]*>/gi) || []).find(t => re.test(t));
          const a = m && /action="([^"]+)"/.exec(m);
          return a ? decode(a[1]) : null;
        },
        // The href of the first <a> whose tag matches re.
        link(html, re) {
          const m = (html.match(/<a\b[^>]*>/gi) || []).find(t => re.test(t));
          const a = m && /href="([^"]+)"/.exec(m);
          return a ? decode(a[1]) : null;
        },
      };
    },
    // Polling: repeat this request (Runner and CLI) until done() holds or the
    // poll limit passes, then run final() once.
    poll(name, done, final, sinceVar = 'change_at') {
      const n = Number(bru.getVar('poll_n') || 0);
      const since = Number(bru.getVar(sinceVar) || Date.now());
      const waited = (Date.now() - since) / 1000;
      const limit = Number(N.v('poll_limit_seconds') || 660);
      let ok = false;
      try { ok = done(); } catch (e) { ok = false; }
      if (!ok && waited < limit) {
        bru.setVar('poll_n', n + 1);
        console.log(`${name}: not yet after ${Math.round(waited)} s; waiting for the next group sync`);
        bru.runner.setNextRequest(name);
        return;
      }
      bru.setVar('poll_n', 0);
      test(`took ${Math.round(waited)} s, within the 10-minute bound`, () => expect(waited).to.be.below(600));
      final();
    },
    // The raw bytes of a top-level member of a JSON object text, exactly as
    // they appear in it (S8: the published schema, byte for byte).
    rawMember(text, key) {
      let i = 0;
      const ws = () => { while (i < text.length && ' \t\r\n'.includes(text[i])) i++; };
      const str = () => {
        const start = i++;
        while (text[i] !== '"') i += text[i] === '\\' ? 2 : 1;
        i++;
        return JSON.parse(text.slice(start, i));
      };
      const value = () => {
        const start = i;
        if (text[i] === '"') { str(); return text.slice(start, i); }
        if (text[i] === '{' || text[i] === '[') {
          let depth = 0;
          for (;;) {
            const ch = text[i];
            if (ch === '"') { str(); continue; }
            if (ch === '{' || ch === '[') depth++;
            if (ch === '}' || ch === ']') { depth--; if (depth === 0) { i++; break; } }
            i++;
          }
          return text.slice(start, i);
        }
        while (i < text.length && !',}] \t\r\n'.includes(text[i])) i++;
        return text.slice(start, i);
      };
      ws();
      if (text[i] !== '{') throw new Error('rawMember: not a JSON object');
      i++;
      for (;;) {
        ws();
        if (text[i] === '}') return undefined;
        const k = str();
        ws(); i++; ws();
        const v = value();
        if (k === key) return v;
        ws();
        if (text[i] === ',') i++;
      }
    },
    sha256: (s) => require('crypto').createHash('sha256').update(Buffer.from(s, 'utf8')).digest('hex'),
    // A file of the repository, read from the collection root
    // (docs/acceptance/guide/bruno/).
    repoFile: (rel) => require('fs').readFileSync(require('path').join(bru.cwd(), '..', '..', '..', '..', rel), 'utf8'),
    async pollWait() {
      if (Number(bru.getVar('poll_n') || 0) > 0) await bru.sleep(Number(N.v('poll_interval_ms') || 10000));
    },
  };
  return N;
};
